<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/sales_step15.php';if(empty($_SESSION['crm_detail_csrf']))$_SESSION['crm_detail_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['crm_detail_csrf'];$error=null;$success=null;$customer=null;$addresses=[];$sales=[];$interactions=[];$customerId=(int)($_GET['id']??$_POST['customer_id']??0);
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];if($customerId<=0)throw new RuntimeException('Choose a Customer Master record.');if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'');if($action==='address'){$id=sales_step15_save_address($pdo,$customerId,$_POST);$success='Address #'.$id.' saved.';}elseif($action==='interaction'){$orderRaw=trim((string)($_POST['order_id']??''));$orderId=$orderRaw===''?null:(int)$orderRaw;$id=sales_step15_add_interaction($pdo,$customerId,$orderId,(string)($_POST['interaction_type']??'note'),(string)($_POST['interaction_date']??date('Y-m-d\TH:i')),trim((string)($_POST['subject']??'')),trim((string)($_POST['notes']??'')),trim((string)($_POST['next_followup_at']??''))?:null);$success='CRM interaction #'.$id.' saved.';}}$customer=sales_step15_customer($pdo,$orgId,$customerId);$stmt=$pdo->prepare("SELECT * FROM crm_customer_addresses WHERE organization_id=? AND customer_id=? AND status='active' ORDER BY is_default DESC,id DESC");$stmt->execute([$orgId,$customerId]);$addresses=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT f.*,o.order_date,sl.sale_status,si.invoice_number FROM sales_fulfillment_ledger f JOIN orders o ON o.id=f.order_id AND o.organization_id=f.organization_id JOIN product_sale_ledger sl ON sl.order_id=f.order_id AND sl.organization_id=f.organization_id LEFT JOIN sales_invoices si ON si.id=f.invoice_id AND si.organization_id=f.organization_id WHERE f.organization_id=? AND f.customer_id=? ORDER BY o.order_date DESC,o.id DESC");$stmt->execute([$orgId,$customerId]);$sales=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT * FROM crm_interactions WHERE organization_id=? AND customer_id=? ORDER BY interaction_date DESC,id DESC LIMIT 120");$stmt->execute([$orgId,$customerId]);$interactions=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function cd_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function cd_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Customer 360 - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="customer_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • Customer 360°</small></span></a><div class="os-top-actions"><a class="os-btn" href="crm_followups.php">Follow-ups</a><a class="os-btn" href="sales_receivables.php">Receivables</a><a class="os-btn primary" href="customer_center.php">Customers</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Customer 360</div><nav class="os-nav"><a href="customer_center.php"><i class="dot"></i>Customer Master</a><a class="active" href="#"><i class="dot"></i>Profile 360°</a><a href="sales_fulfillment.php"><i class="dot"></i>Sales Fulfillment</a><a href="crm_followups.php"><i class="dot"></i>Follow-ups</a></nav></aside><main class="os-main"><?php if($error):?><div class="pp-alert bad"><strong>Customer diagnostic:</strong> <?= cd_h($error) ?></div><?php elseif($customer):?><section class="os-hero pp-hero"><div class="os-kicker">CUSTOMER 360° • <?= cd_h($customer['customer_code']) ?></div><h1><?= cd_h($customer['customer_name']) ?></h1><p><?= cd_h($customer['mobile']?:'No mobile') ?><?= $customer['email']?' • '.cd_h($customer['email']):'' ?> • <?= cd_h(strtoupper($customer['customer_type'])) ?><?= $customer['member_id']?' • Verified Member #'.(int)$customer['member_id']:'' ?></p><div class="os-status-row"><span class="os-chip good"><?= cd_h(strtoupper($customer['status'])) ?></span><span class="os-chip"><?= count($sales) ?> linked sales</span><span class="os-chip"><?= count($interactions) ?> CRM events</span></div></section><?php if($success):?><div class="pp-alert good"><strong>Saved:</strong> <?= cd_h($success) ?></div><?php endif;?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-5"><h2>Add Delivery Address</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= cd_h($csrf) ?>"><input type="hidden" name="action" value="address"><input type="hidden" name="customer_id" value="<?= $customerId ?>"><label>Type<select name="address_type"><option value="delivery">Delivery</option><option value="billing">Billing</option><option value="home">Home</option><option value="office">Office</option></select></label><label>Address Line 1<input name="address_line1" required></label><label>Address Line 2<input name="address_line2"></label><label>City<input name="city"></label><label>District<input name="district"></label><label>State<input name="state_name" value="Uttar Pradesh"></label><label>PIN<input name="postal_code"></label><label><input type="checkbox" name="is_default" value="1"> Set as default</label><button>Save Address →</button></form><h2 style="margin-top:18px">Saved Addresses</h2><?php foreach($addresses as $a):?><div class="pp-source"><b><?= cd_h(ucfirst($a['address_type'])) ?><?= $a['is_default']?' • Default':'' ?></b><span><?= cd_h(implode(', ',array_filter([$a['address_line1'],$a['address_line2'],$a['city'],$a['district'],$a['state_name'],$a['postal_code']]))) ?></span></div><?php endforeach;?><?php if(!$addresses):?><p>No address saved yet.</p><?php endif;?></article><article class="os-card pp-span-7"><h2>Add CRM Interaction / Follow-up</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= cd_h($csrf) ?>"><input type="hidden" name="action" value="interaction"><input type="hidden" name="customer_id" value="<?= $customerId ?>"><label>Type<select name="interaction_type"><option value="call">Call</option><option value="whatsapp">WhatsApp</option><option value="visit">Visit</option><option value="followup">Follow-up</option><option value="complaint">Complaint</option><option value="support">Support</option><option value="note">Note</option></select></label><label>Date / Time<input type="datetime-local" name="interaction_date" value="<?= cd_h(date('Y-m-d\TH:i')) ?>" required></label><label>Linked Sale (optional)<select name="order_id"><option value="">No sale link</option><?php foreach($sales as $s):?><option value="<?= (int)$s['order_id'] ?>">Order #<?= (int)$s['order_id'] ?> • <?= cd_h($s['order_date']) ?> • <?= cd_m($s['effective_charge']) ?></option><?php endforeach;?></select></label><label>Subject<input name="subject"></label><label>Notes<textarea name="notes" rows="3" required></textarea></label><label>Next Follow-up (optional)<input type="datetime-local" name="next_followup_at"></label><button>Save CRM Activity →</button></form></article><article class="os-card pp-span-7"><h2>Linked Sales</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Order</th><th>Date</th><th>Invoice</th><th>Effective Charge</th><th>Collected</th><th>Receivable</th><th>Delivery</th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td><a href="sales_fulfillment.php?order=<?= (int)$s['order_id'] ?>"><b>#<?= (int)$s['order_id'] ?></b></a><small><?= cd_h(strtoupper($s['sale_status'])) ?></small></td><td><?= cd_h($s['order_date']) ?></td><td><?= cd_h($s['invoice_number']?:'—') ?></td><td><?= cd_m($s['effective_charge']) ?></td><td><?= cd_m($s['net_collected']) ?></td><td><b><?= cd_m($s['receivable_amount']) ?></b></td><td><?= cd_h(strtoupper($s['delivery_status'])) ?></td></tr><?php endforeach;?><?php if(!$sales):?><tr><td colspan="7">No sales explicitly linked to this customer yet.</td></tr><?php endif;?></tbody></table></div></article><article class="os-card pp-span-5"><h2>CRM Timeline</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Type</th><th>Activity</th><th>Next</th></tr></thead><tbody><?php foreach($interactions as $i):?><tr><td><?= cd_h(substr($i['interaction_date'],0,16)) ?></td><td><?= cd_h(strtoupper($i['interaction_type'])) ?><small><?= cd_h(strtoupper($i['status'])) ?></small></td><td><b><?= cd_h($i['subject']?:'CRM activity') ?></b><small><?= cd_h($i['notes']) ?></small></td><td><?= cd_h($i['next_followup_at']?substr($i['next_followup_at'],0,16):'—') ?></td></tr><?php endforeach;?><?php if(!$interactions):?><tr><td colspan="4">No CRM interactions yet.</td></tr><?php endif;?></tbody></table></div></article></section><div class="os-footer-note"><strong>Customer 360 rule:</strong> contact, address, sale, balance and interaction history remain separate traceable facts.</div><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
